extends "res://htd/htd_test.gd"


func _find_all_in_group(root: Node, group_name: String) -> Array[Node]:
	var found: Array[Node] = []
	var stack: Array[Node] = [root]
	while not stack.is_empty():
		var node: Node = stack.pop_back()
		if node.is_in_group(group_name):
			found.append(node)
		for child in node.get_children():
			stack.append(child)
	return found


func _run_tests() -> void:
	# 1. Verifica nemico walker
	var walker := await instantiate_scene("res://enemies/walker_enemy.tscn")
	if not check("walker_scene", walker != null and _find_all_in_group(walker, "enemies").size() > 0, "res://enemies/walker_enemy.tscn deve esistere e appartenere al gruppo 'enemies'"):
		return

	# 2. Verifica nemico flyer
	var flyer := await instantiate_scene("res://enemies/flyer_enemy.tscn")
	if not check("flyer_scene", flyer != null and _find_all_in_group(flyer, "enemies").size() > 0, "res://enemies/flyer_enemy.tscn deve esistere e appartenere al gruppo 'enemies'"):
		return

	# 3. Verifica Livello 1
	var lvl1 := await instantiate_scene("res://levels/level_1.tscn")
	if not check("lvl1_loads", lvl1 != null, "La scena res://levels/level_1.tscn deve aprirsi senza errori"):
		return

	var player1 := find_by_name(lvl1, "Player")
	if player1 == null:
		player1 = find_by_class(lvl1, "CharacterBody2D")
	if not check("lvl1_player", player1 != null, "Il livello 1 deve contenere un'istanza del Player"):
		return

	var cp1 := _find_all_in_group(lvl1, "checkpoints")
	if not check("lvl1_checkpoint", cp1.size() >= 1, "Il livello 1 deve contenere almeno una bandierina (nel gruppo 'checkpoints')"):
		return

	var goal1 := _find_all_in_group(lvl1, "goals")
	if not check("lvl1_goal", goal1.size() >= 1, "Il livello 1 deve contenere un traguardo (nel gruppo 'goals')"):
		return

	var has_respawn_prop := "respawn_point" in player1
	var has_respawn_func := has_function(player1, "respawn")
	if not check("player_respawn_contract", has_respawn_prop and has_respawn_func, "Il Player deve avere la variabile respawn_point e la funzione respawn()"):
		return

	var initial_respawn = get_prop(player1, "respawn_point")
	player1.global_position = cp1[0].global_position
	await wait_physics_frames(5)
	if get_prop(player1, "respawn_point") == initial_respawn and cp1[0] is Area2D:
		cp1[0].body_entered.emit(player1)
		await wait_physics_frames(2)

	var new_respawn: Vector2 = get_prop(player1, "respawn_point", Vector2.ZERO)
	check("checkpoint_updates", new_respawn.distance_to(cp1[0].global_position) < 20.0, "Toccando la bandierina, respawn_point del Player deve aggiornarsi alla posizione del checkpoint")

	player1.global_position = Vector2(9999.0, 9999.0)
	call_if_exists(player1, "respawn")
	check("respawn_teleport", player1.global_position.distance_to(new_respawn) < 5.0, "La funzione respawn() deve riposizionare il personaggio su respawn_point")

	# 4. Verifica Livello 2
	var lvl2 := await instantiate_scene("res://levels/level_2.tscn")
	if not check("lvl2_loads", lvl2 != null, "La scena res://levels/level_2.tscn deve aprirsi senza errori"):
		return

	var player2 := find_by_name(lvl2, "Player")
	if player2 == null:
		player2 = find_by_class(lvl2, "CharacterBody2D")
	if not check("lvl2_player", player2 != null, "Il livello 2 deve contenere un'istanza del Player"):
		return

	var cp2 := _find_all_in_group(lvl2, "checkpoints")
	var goal2 := _find_all_in_group(lvl2, "goals")
	var hazards2 := _find_all_in_group(lvl2, "hazards")
	var enemies2 := _find_all_in_group(lvl2, "enemies")

	check("lvl2_elements", cp2.size() >= 1 and goal2.size() >= 1, "Il livello 2 deve contenere almeno una bandierina e un traguardo")
	check("lvl2_hazards", hazards2.size() >= 1, "Il livello 2 deve contenere pericoli (nel gruppo 'hazards')")
	check("lvl2_enemies", enemies2.size() >= 1, "Il livello 2 deve contenere almeno un nemico (nel gruppo 'enemies')")

	if hazards2.size() > 0:
		player2.global_position = hazards2[0].global_position
		await wait_physics_frames(5)
		if hazards2[0] is Area2D and player2.global_position.distance_to(hazards2[0].global_position) < 5.0:
			hazards2[0].body_entered.emit(player2)
			await wait_physics_frames(2)
		check("hazard_death", player2.global_position.distance_to(hazards2[0].global_position) > 10.0, "Toccando un pericolo (gruppo 'hazards'), il personaggio deve morire e rinascere al respawn_point")

	# 5. Verifica Livello 3
	var lvl3 := await instantiate_scene("res://levels/level_3.tscn")
	if not check("lvl3_loads", lvl3 != null, "La scena res://levels/level_3.tscn deve aprirsi senza errori"):
		return

	var player3 := find_by_name(lvl3, "Player")
	if player3 == null:
		player3 = find_by_class(lvl3, "CharacterBody2D")
	if not check("lvl3_player", player3 != null, "Il livello 3 deve contenere un'istanza del Player"):
		return

	var cp3 := _find_all_in_group(lvl3, "checkpoints")
	var goal3 := _find_all_in_group(lvl3, "goals")
	var hazards3 := _find_all_in_group(lvl3, "hazards")
	var enemies3 := _find_all_in_group(lvl3, "enemies")

	check("lvl3_elements", cp3.size() >= 1 and goal3.size() >= 1 and hazards3.size() >= 1, "Il livello 3 deve contenere bandierina, traguardo e pericoli")
	check("lvl3_enemies", enemies3.size() >= 2, "Il livello 3 deve contenere almeno due nemici (nel gruppo 'enemies')")

